def generate_lines(n):
    for i in range(n):
        yield '{"id": ' + str(i) + '}\n'

if __name__ == "__main__":
    import sys
    n = int(sys.argv[1]) if len(sys.argv) > 1 else 10
    with open("output.jsonl", "w") as f:
        for line in generate_lines(n):
            f.write(line)
